module SRT_Divider (
    input clk,
    input rst,
    input start,
    input [15:0] numerator,
    input [15:0] denominator,
    output reg [15:0] quotient,
    output reg [15:0] remainder,
    output reg done
);
    reg [15:0] A, B, Q;
    reg [4:0] count; // Count for iterations

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            quotient <= 0;
            remainder <= 0;
            done <= 0;
            A <= 0;
            B <= 0;
            Q <= 0;
            count <= 0;
        end else if (start) begin
            A <= numerator;
            B <= denominator;
            Q <= 0;
            count <= 16; // Assume 16 iterations for fixed-point division
            done <= 0;
        end else if (count > 0) begin
            // SRT division process (simplified)
            if (A >= B) begin
                A <= A - B; // Subtract the denominator from numerator
                Q <= Q + 1; // Increment quotient
            end
            count <= count - 1;
        end else begin
            quotient <= Q;
            remainder <= A;
            done <= 1; // Indicate division is done
        end
    end
endmodule

