module i2c_master (  
    input wire clk,  
    input wire rst,  
    input wire [7:0] data_in,  
    input wire start,  
    output reg [7:0] data_out,  
    output reg scl,  
    output reg sda,  
    output reg busy  
);  

    parameter IDLE = 3'b000,  
              START = 3'b001,  
              WRITE = 3'b010,  
              READ = 3'b011,  
              STOP = 3'b100;  

    reg [2:0] state, next_state;  
    reg [3:0] bit_cnt;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            busy <= 0;  
            scl <= 1;  
            sda <= 1;  
            bit_cnt <= 0;  
        end else begin  
            state <= next_state;  
        end  
    end  

    always @(*) begin  
        next_state = state;  
        case (state)  
            IDLE: if (start) begin  
                       next_state = START;  
                       busy = 1;  
                   end  
            START: begin  
                        sda = 0;  
                        scl = 0;  
                        next_state = WRITE;  
                   end  
            WRITE: begin  
                        if (bit_cnt < 8) begin  
                            sda = data_in[7 - bit_cnt];  
                            scl = 0;  
                            next_state = WRITE;  
                            bit_cnt = bit_cnt + 1;  
                        end else begin  
                            scl = 1;  
                            next_state = READ;  
                        end  
                   end  
            READ: begin  
                        scl = 0;  
                        // Simulating receiving data  
                        data_out[7 - bit_cnt] = sda;  
                        bit_cnt = bit_cnt + 1;  
                        if (bit_cnt == 8) begin  
                            next_state = STOP;  
                        end  
                   end  
            STOP: begin  
                        sda = 1;  
                        scl = 1;  
                        busy = 0;  
                        next_state = IDLE;  
                   end  
        endcase  
    end  
endmodule

