module watchdog_timer(  
    input clk,  
    input reset,  
    input enable,  
    output reg timeout  
);  
    parameter TIME_LIMIT = 10;  
    reg [3:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            count <= 0;  
            timeout <= 0;  
        end else if (enable) begin  
            if (count < TIME_LIMIT) begin  
                count <= count + 1;  
                timeout <= 0;  
            end else begin  
                timeout <= 1;  
            end  
        end  
    end  
endmodule

