module csprng (
    input clk,
    input reset,
    output reg [7:0] random_number
);
    reg [7:0] lfsr;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            lfsr <= 8'b10101010; // Seed value
        end else begin
            lfsr <= {lfsr[6:0], lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3]};
        end
        random_number <= lfsr;
    end
endmodule

module matrix_multiplier (  
    input [3:0] a11, a12,  
    input [3:0] a21, a22,  
    input [3:0] b11, b12,  
    input [3:0] b21, b22,  
    output reg [7:0] c11, c12,  
    output reg [7:0] c21, c22  
);  
    always @(*) begin  
        c11 = a11 * b11 + a12 * b21;  
        c12 = a11 * b12 + a12 * b22;  
        c21 = a21 * b11 + a22 * b21;  
        c22 = a21 * b12 + a22 * b22;  
    end  
endmodule

