module uart_tx (
    input clk,
    input reset,
    input start,
    input [7:0] data,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE_DIV = 104; // Example for 9600 baud with 100MHz clock
    parameter IDLE = 0, START_BIT = 1, DATA_BITS = 2, STOP_BIT = 3;

    reg [1:0] state = IDLE;
    reg [3:0] bit_index = 0;
    reg [7:0] tx_data;
    reg [6:0] baud_count = 0;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1;
            busy <= 0;
            baud_count <= 0;
            bit_index <= 0;
        end else begin
            case (state)
                IDLE: begin
                    tx <= 1; // Idle state is high
                    busy <= 0;
                    if (start) begin
                        tx_data <= data;
                        state <= START_BIT;
                        busy <= 1;
                    end
                end
                START_BIT: begin
                    if (baud_count < BAUD_RATE_DIV) begin
                        baud_count <= baud_count + 1;
                    end else begin
                        baud_count <= 0;
                        tx <= 0; // Start bit is low
                        state <= DATA_BITS;
                    end
                end
                DATA_BITS: begin
                    if (baud_count < BAUD_RATE_DIV) begin
                        baud_count <= baud_count + 1;
                    end else begin
                        baud_count <= 0;
                        tx <= tx_data[bit_index]; // Transmit data bits
                        if (bit_index < 7) begin
                            bit_index <= bit_index + 1;
                        end else begin
                            bit_index <= 0;
                            state <= STOP_BIT;
                        end
                    end
                end
                STOP_BIT: begin
                    if (baud_count < BAUD_RATE_DIV) begin
                        baud_count <= baud_count + 1;
                    end else begin
                        baud_count <= 0;
                        tx <= 1; // Stop bit is high
                        state <= IDLE;
                        busy <= 0;
                    end
                end
            endcase
        end
    end
endmodule

