module instruction_pipeline (
    input clk,
    input rst,
    input [4:0] instruction_in,
    output reg [4:0] instruction_out
);

    reg [4:0] fetch_reg, decode_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            fetch_reg <= 5'b00000;
            decode_reg <= 5'b00000;
            instruction_out <= 5'b00000;
        end else begin
            fetch_reg <= instruction_in; // Fetch stage
            decode_reg <= fetch_reg;      // Decode stage
            instruction_out <= decode_reg; // Execute stage
        end
    end

endmodule

