module viterbi_decoder (  
    input clk,  
    input reset,  
    input [1:0] received_bits,  
    output reg [1:0] decoded_bits,  
    output reg valid_output  
);  

    reg [1:0] state;  
    reg [1:0] next_state;  

    parameter STATE_0 = 2'b00;  
    parameter STATE_1 = 2'b01;  
    parameter STATE_2 = 2'b10;  
    parameter STATE_3 = 2'b11;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= STATE_0;  
            valid_output <= 0;  
        end else begin  
            state <= next_state;  
            valid_output <= 1;  
        end  
    end  

    always @(*) begin  
        case (state)  
            STATE_0: begin  
                if (received_bits == 2'b00) begin  
                    next_state = STATE_0;  
                    decoded_bits = 2'b00;  
                end else begin  
                    next_state = STATE_1;  
                    decoded_bits = 2'b01;  
                end  
            end  
            STATE_1: begin  
                if (received_bits == 2'b00) begin  
                    next_state = STATE_2;  
                    decoded_bits = 2'b10;  
                end else begin  
                    next_state = STATE_3;  
                    decoded_bits = 2'b11;  
                end  
            end  
            STATE_2: begin  
                if (received_bits == 2'b00) begin  
                    next_state = STATE_0;  
                    decoded_bits = 2'b00;  
                end else begin  
                    next_state = STATE_1;  
                    decoded_bits = 2'b01;  
                end  
            end  
            STATE_3: begin  
                if (received_bits == 2'b00) begin  
                    next_state = STATE_2;  
                    decoded_bits = 2'b10;  
                end else begin  
                    next_state = STATE_3;  
                    decoded_bits = 2'b11;  
                end  
            end  
            default: begin  
                next_state = STATE_0;  
                decoded_bits = 2'b00;  
            end  
        endcase  
    end  
endmodule

