module d_flip_flop (
    input wire D,
    input wire CLK,
    input wire RST,
    output reg Q,
    output wire Qn
);
    assign Qn = ~Q;

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            Q <= 1'b0;
        end else begin
            Q <= D;
        end
    end
endmodule

