module fft_64point (
    input wire clk,
    input wire reset,
    input wire [63:0] data_in,
    output reg [63:0] data_out,
    output reg done
);
    reg [5:0] state;
    parameter IDLE = 6'b000001, PROCESS = 6'b000010, DONE = 6'b000100;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            data_out <= 64'b0;
            done <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in != 64'b0) begin
                        state <= PROCESS;
                    end
                end
                PROCESS: begin
                    // Simulated FFT process (for illustration purposes)
                    data_out <= data_in ^ 64'hA5A5A5A5A5A5A5A5; // Dummy operation
                    state <= DONE;
                end
                DONE: begin
                    done <= 1;
                    state <= IDLE; // Go back to IDLE after processing
                end
            endcase
        end
    end
endmodule

