module pitch_detector (
    input wire clk,
    input wire pitch_in,
    output reg detected
);
    reg [3:0] state;

    always @(posedge clk) begin
        if (pitch_in) begin
            state <= state + 1;
        end else begin
            state <= 0;
        end

        // Assume we detect a pitch when state equals 10
        if (state == 10) begin
            detected <= 1;
        end else begin
            detected <= 0;
        end
    end
endmodule

