module iir_filter (
    input clk,
    input rst,
    input [15:0] x_in,
    output reg [15:0] y_out
);
    parameter a1 = 16'h0A00; // Coefficient a1
    parameter a2 = 16'h0A00; // Coefficient a2
    parameter b1 = 16'h0A00; // Coefficient b1
    parameter b2 = 16'h0A00; // Coefficient b2

    reg [15:0] x_delay [0:3]; // Delay line for input samples
    reg [15:0] y_delay [0:3]; // Delay line for output samples

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y_out <= 16'b0;
            x_delay[0] <= 16'b0;
            x_delay[1] <= 16'b0;
            x_delay[2] <= 16'b0;
            x_delay[3] <= 16'b0;
            y_delay[0] <= 16'b0;
            y_delay[1] <= 16'b0;
            y_delay[2] <= 16'b0;
            y_delay[3] <= 16'b0;
        end else begin
            // Shift the input samples
            x_delay[3] <= x_delay[2];
            x_delay[2] <= x_delay[1];
            x_delay[1] <= x_delay[0];
            x_delay[0] <= x_in;

            // Shift the output samples
            y_delay[3] <= y_delay[2];
            y_delay[2] <= y_delay[1];
            y_delay[1] <= y_delay[0];

            // Compute the output sample
