module viterbi_decoder (
    input clk,
    input reset,
    input data_in,
    output reg [1:0] decoded_out
);

    reg [1:0] state, next_state;

    // Define states
    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (state)
            S0: next_state = data_in ? S1 : S0;
            S1: next_state = data_in ? S2 : S0;
            S2: next_state = data_in ? S3 : S1;
            S3: next_state = data_in ? S3 : S2;
            default: next_state = S0;
        endcase
    end

    // Output logic
    always @(state) begin
        case (state)
            S0: decoded_out = 2'b00;
            S1: decoded_out = 2'b01;
            S2: decoded_out = 2'b10;
            S3: decoded_out = 2'b11;
            default: decoded_out = 2'b00;
        endcase
    end
endmodule

