module butterworth_filter (  
    input clk,  
    input reset,  
    input [7:0] x,  
    output reg [7:0] y  
);  
    reg [15:0] a1, a2;  
    reg [15:0] b0, b1, b2;  
    reg [15:0] x_delay1, x_delay2;  
    reg [15:0] y_delay1, y_delay2;  

    // Coefficients for a 2nd order Butterworth filter (example coefficients)
    initial begin  
        b0 = 16'h1;  
        b1 = 16'h2;  
        b2 = 16'h1;  
        a1 = 16'h3;  
        a2 = 16'h1;  
    end  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            y <= 8'h00;  
            x_delay1 <= 16'h00;  
            x_delay2 <= 16'h00;  
            y_delay1 <= 16'h00;  
            y_delay2 <= 16'h00;  
        end else begin  
            // 2nd order Butterworth filter difference equation
            y <= (b0 * x + b1 * x_delay1 + b2 * x_delay2 - a1 * y_delay1 - a2 * y_delay2) >> 4;  
            // Update delays
            x_delay2 <= x_delay1;  
            x_delay1 <= x;  
            y_delay2 <= y_delay1;  
            y_delay1 <= y;  
        end  
    end  
endmodule

