module serializer_32bit (  
    input clk,  
    input reset,  
    input [31:0] data_in,  
    input valid,  
    output reg serial_out,  
    output reg data_valid  
);  
    reg [31:0] shift_reg;  
    reg [4:0] bit_count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 32'b0;  
            bit_count <= 5'd0;  
            serial_out <= 1'b0;  
            data_valid <= 1'b0;  
        end else begin  
            if (valid && bit_count == 5'd0) begin  
                shift_reg <= data_in;  
                bit_count <= 5'd31;  
                data_valid <= 1'b1;  
            end else if (bit_count > 0) begin  
                serial_out <= shift_reg[0];  
                shift_reg <= shift_reg >> 1;  
                bit_count <= bit_count - 1;  
            end else begin  
                data_valid <= 1'b0;  
            end  
        end  
    end  
endmodule

