module deserializer (
    input wire clk,
    input wire reset,
    input wire serial_in,
    output reg [15:0] parallel_out
);
    reg [3:0] bit_counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            parallel_out <= 16'b0;
            bit_counter <= 4'b0;
        end else if (bit_counter < 16) begin
            parallel_out <= {serial_in, parallel_out[15:1]};
            bit_counter <= bit_counter + 1;
        end
    end
endmodule

