module dac_8bit (
    input [7:0] data_in,  // 8-bit input data
    output reg [9:0] voltage_out // 10-bit output voltage representation
);
    always @(*) begin
        // Scale the 8-bit input to 10-bit output for 0V to 1V range
        voltage_out = (data_in * 1023) / 255; // Scale to 10-bit
    end
endmodule

module checksum (
    input [4:0] data_in,
    output checksum_out
);
    assign checksum_out = ^data_in; // XOR reduction to compute parity
endmodule

module vco (  
    input wire clk,  
    input wire reset,  
    input wire [3:0] control,  
    output reg out  
);  

    reg [3:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            out <= 0;  
        end else begin  
            counter <= counter + 1;  
            if (counter >= control) begin  
                out <= ~out;  
                counter <= 0;  
            end  
        end  
    end  
endmodule

module or_gate (
    input wire a,
    input wire b,
    input wire c,
    output wire y
);
    assign y = a | b | c;
endmodule

module ethernet_mac_controller(
    input clk,
    input reset,
    input start,
    input ack,
    output reg [1:0] state // 00: IDLE, 01: TRANSMITTING, 10: WAITING_FOR_ACK
);
    // State encoding
    parameter IDLE = 2'b00;
    parameter TRANSMITTING = 2'b01;
    parameter WAITING_FOR_ACK = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= TRANSMITTING;
                    end
                end
                TRANSMITTING: begin
                    state <= WAITING_FOR_ACK;
                end
                WAITING_FOR_ACK: begin
                    if (ack) begin
                        state <= IDLE;
                    end
                end
            endcase
        end
    end
endmodule

