module dma_controller (
    input clk,
    input rst,
    input start,
    input [7:0] src_addr,
    input [7:0] dest_addr,
    inout [7:0] data_bus,
    output reg busy
);
    reg [3:0] state;
    reg [7:0] src_reg;
    reg [7:0] dest_reg;
    reg [7:0] data;
    reg [3:0] count;

    parameter IDLE = 4'b0000;
    parameter TRANSFER = 4'b0001;
    parameter DONE = 4'b0010;

    assign data_bus = (state == TRANSFER) ? data : 8'bz;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            busy <= 0;
            count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        src_reg <= src_addr;
                        dest_reg <= dest_addr;
                        busy <= 1;
                        count <= 8; // Transfer 8 bytes
                        state <= TRANSFER;
                    end
                end
                TRANSFER: begin
                    if (count > 0) begin
                        data <= src_reg;  // Simulate reading from source
                        dest_reg <= dest_addr; // Simulate writing to destination
                        count <= count - 1;
                    end else begin
                        state <= DONE;
                    end
                end
                DONE: begin
                    busy <= 0;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

