module pulse_generator(  
    input clk,  
    input rst,  
    output reg pulse  
);  
    reg [3:0] counter;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            pulse <= 0;  
            counter <= 0;  
        end else begin  
            if (counter < 5) begin  
                pulse <= 1;  
                counter <= counter + 1;  
            end else if (counter < 10) begin  
                pulse <= 0;  
                counter <= counter + 1;  
            end else begin  
                counter <= 0;  
            end  
        end  
    end  
endmodule

