module fir_filter(input [7:0] x0, x1, x2, x3, output reg [15:0] y);  
    // Define filter coefficients  
    parameter COEFF0 = 8'd1;  
    parameter COEFF1 = 8'd2;  
    parameter COEFF2 = 8'd3;  
    parameter COEFF3 = 8'd4;  

    always @(*) begin  
        // Compute the output sample using the FIR filter formula  
        y = (COEFF0 * x0) + (COEFF1 * x1) + (COEFF2 * x2) + (COEFF3 * x3);  
    end  
endmodule

module branch_predictor(  
    input clk,  
    input reset,  
    input branch_outcome, // 1 for taken, 0 for not taken  
    output reg prediction // 1 for taken, 0 for not taken  
);  
    reg [1:0] state;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= 2'b00; // Initial state is strongly not taken  
            prediction <= 1'b0;  
        end else begin  
            case (state)  
                2'b00: begin // Strongly not taken  
                    prediction <= 1'b0;  
                    if (branch_outcome) state <= 2'b01;  
                end  
                2'b01: begin // Weakly not taken  
                    prediction <= 1'b0;  
                    if (branch_outcome) state <= 2'b10;  
                    else state <= 2'b00;  
                end  
                2'b10: begin // Weakly taken  
                    prediction <= 1'b1;  
                    if (branch_outcome) state <= 2'b11;  
                    else state <= 2'b01;  
                end  
                2'b11: begin // Strongly taken  
                    prediction <= 1'b1;  
                    if (branch_outcome) state <= 2'b11;  
                    else state <= 2'b10;  
                end  
            endcase  
        end  
    end  
endmodule

module divide_by_4 (  
