module pulse_generator(
    input clk,
    input reset,
    input [3:0] N, // 4-bit input for N, max value is 15
    output reg pulse
);
    reg [3:0] counter;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            pulse <= 0;
        end else begin
            if (counter < N) begin
                pulse <= 0;
                counter <= counter + 1;
            end else if (counter == N) begin
                pulse <= 1; // Generate pulse
                counter <= 0; // Reset counter
            end
        end
    end
endmodule

