module spi_controller (  
    input wire clk,  
    input wire cs,  
    input wire data_in,  
    output reg [7:0] data_out,  
    output reg data_ready  
);  
    reg [2:0] bit_count;  

    always @(posedge clk or negedge cs) begin  
        if (!cs) begin  
            // Reset when chip select is inactive  
            bit_count <= 3'b000;  
            data_out <= 8'b0;  
            data_ready <= 0;  
        end else if (bit_count < 3'b111) begin  
            // Shift in data on the rising edge of clk while cs is active  
            data_out <= {data_out[6:0], data_in};  
            bit_count <= bit_count + 1;  
        end else begin  
            // Set data ready signal when 8 bits are received  
            data_ready <= 1;  
        end  
    end  
endmodule

