module pulse_generator(
    input wire clk,
    input wire reset,
    input wire trigger,
    input wire [7:0] PULSE_WIDTH, // Pulse width in clock cycles
    output reg pulse_out
);
    reg [7:0] counter;
    reg is_pulsing;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pulse_out <= 0;
            counter <= 0;
            is_pulsing <= 0;
        end else if (trigger && !is_pulsing) begin
            is_pulsing <= 1;
            counter <= 0;
            pulse_out <= 1;
        end else if (is_pulsing) begin
            if (counter < PULSE_WIDTH - 1) begin
                counter <= counter + 1;
                pulse_out <= 1;
            end else begin
                is_pulsing <= 0;
                pulse_out <= 0;
            end
        end
    end
endmodule

